export const getDeleteSharedItemUrl = (token: string,
    itemId: string,
    params?: DeleteSharedItemParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/tasks-api/shared/${token}/items/${itemId}?${stringifiedParams}` : `/tasks-api/shared/${token}/items/${itemId}`
}

